1	import { SovereignBridge } from "./SovereignBridge";
2	import * as fs from "fs";
3	import * as path from "path";
4	import { GameCacheLoader } from "../cache/sqlite";
5	import { parse } from "../opdecoder";
6	import { cacheMajors, cacheMapFiles } from "../constants";
7	
8	/**
9	 * SovereignWorldLoader.ts
10	 * 
11	 * Bridges the "Gold Mine" (unified_extract/world_extract JSONs) 
12	 * into the interactive 3D Sovereign Engine.
13	 */
14	
15	const UNIFIED_DIR = "D:\\sovereign\\atlas\\spatial\\unified_extract";
16	const WORLD_EXTRACT_DIR = "D:\\sovereign\\atlas\\spatial\\world_extract";
17	
18	export interface SovereignEntity {
19	    id: number;
20	    type: 'npc' | 'object';
21	    name: string;
22	    x: number;
23	    y: number;
24	    plane: number;
25	    rotation?: number;
26	    wikiUrl?: string;
27	}
28	
29	export interface CollisionTile {
30	    walkable: boolean;
31	    surfaceType: string;
32	    sourceFlags: number;
33	    edges: {
34	        northBlocked?: boolean;
35	        southBlocked?: boolean;
36	        eastBlocked?: boolean;
37	        westBlocked?: boolean;
38	    };
39	}
40	
41	export interface RegionTruth {
42	    regionId: number;
43	    entities: SovereignEntity[];
44	    collisionMatrix: Record<string, CollisionTile>;
45	}
46	
47	export class SovereignWorldLoader {
48	    private static instance: SovereignWorldLoader;
49	    private cache: Map<string, RegionTruth> = new Map();
50	    private cacheSubstrate: GameCacheLoader | null = null;
51	
52	    static getInstance() {
53	        if (!this.instance) this.instance = new SovereignWorldLoader();
54	        return this.instance;
55	    }
56	
57	    public setCacheSubstrate(loader: GameCacheLoader) {
58	        this.cacheSubstrate = loader;
59	        console.log(`[SovereignWorldLoader] Direct Cache Substrate Linked.`);
60	    }
61	
62	    /**
63	     * Loads 1:1 world truth for a specific region.
64	     * Prioritizes 'unified_extract' (High Fidelity) over 'world_extract', 
65	     * and falls back to Direct Cache Materialization.
66	     */
67	    async loadRegionTruth(rx: number, ry: number): Promise<RegionTruth | null> {
68	        const cacheKey = `${rx}_${ry}`;
69	        if (this.cache.has(cacheKey)) return this.cache.get(cacheKey)!;
70	
71	        const fileName = `ms_${rx}_${ry}.json`;
72	        const paths = [
73	            path.join(UNIFIED_DIR, fileName),
74	            path.join(WORLD_EXTRACT_DIR, fileName)
75	        ];
76	
77	        for (const p of paths) {
78	            if (fs.existsSync(p)) {
79	                try {
80	                    const data = JSON.parse(fs.readFileSync(p, 'utf8'));
81	                    console.log(`🧬⚡ Hydro-Synthesized Region [${rx}, ${ry}] from ${p}`);
82	                    const truth = this.normalizeData(data);
83	                    this.cache.set(cacheKey, truth);
84	                    return truth;
85	                } catch (e) {
86	                    console.error(`  [ERR] Failed to parse world truth at ${p}:`, e);
87	                }
88	            }
89	        }
90	
91	        // --- Direct Cache Materialization Baseline ---
92	        if (this.cacheSubstrate) {
93	            console.log(`[SovereignWorldLoader] No pre-synthesized truth for [${rx}, ${ry}]. Triggering Direct Cache Materialization...`);
94	            const truth = await this.materializeFromCache(rx, ry);
95	            if (truth) {
96	                this.cache.set(cacheKey, truth);
97	                return truth;
98	            }
99	        }
100	
101	        console.warn(`  [WARN] No pre-synthesized truth found for region [${rx}, ${ry}]`);
102	        return null;
103	    }
104	
105	    private async materializeFromCache(rx: number, ry: number): Promise<RegionTruth | null> {
106	        if (!this.cacheSubstrate) return null;
107	
108	        const regionId = (rx << 8) | ry;
109	        try {
110	            const index = await this.cacheSubstrate.getCacheIndex(cacheMajors.mapsquares);
111	            const archive = index[regionId];
112	
113	            if (!archive) {
114	                console.warn(`[SovereignWorldLoader] No cache archive for region ${regionId}`);
115	                return null;
116	            }
117	
118	            const files = await this.cacheSubstrate.getFileArchive(archive);
119	            const terrainFile = files.find(f => f.fileid === cacheMapFiles.squares);
120	            const locationFile = files.find(f => f.fileid === cacheMapFiles.locations);
121	
122	            if (!terrainFile || !locationFile) {
123	                console.warn(`[SovereignWorldLoader] Missing terrain/locations in cache archive ${regionId}`);
124	                return null;
125	            }
126	
127	            // Using buildnr 927 as the standard 2026 baseline for now
128	            const terrain = parse.mapsquareTiles.read(terrainFile.buffer, this.cacheSubstrate, { clientVersion: 927 });
129	            const locations = parse.mapsquareLocations.read(locationFile.buffer, this.cacheSubstrate);
130	
131	            const entities: SovereignEntity[] = [];
132	            const collisionMatrix: Record<string, CollisionTile> = {};
133	            const baseX = rx * 64;
134	            const baseY = ry * 64;
135	            const tilesPerLevel = 64 * 64;
136	
137	            // 1. Build Collision from Terrain
138	            for (let plane = 0; plane < 4; plane++) {
139	                for (let ty = 0; ty < 64; ty++) {
140	                    for (let tx = 0; tx < 64; tx++) {
141	                        const tileIndex = (plane * tilesPerLevel) + (ty * 64) + tx;
142	                        const tile = terrain.tiles?.[tileIndex];
143	                        if (!tile) continue;
144	
145	                        const worldX = baseX + tx;
146	                        const worldY = baseY + ty;
147	                        const key = `${worldX}_${worldY}`;
148	
149	                        const settings = tile.settings ?? 0;
150	                        collisionMatrix[key] = {
151	                            walkable: (settings & 1) === 0,
152	                            surfaceType: 'terrain',
153	                            sourceFlags: settings,
154	                            edges: {}
155	                        };
156	                    }
157	                }
158	            }
159	
160	            // 2. Build Entities and Update Collision from Locations
161	            for (const locGroup of locations.locations) {
162	                const objId = locGroup.id;
163	                let objDef: any;
164	                try {
165	                    objDef = await this.getObjectDef(objId);
166	                } catch { continue; }
167	
168	                for (const use of locGroup.uses) {
169	                    const worldX = baseX + use.x;
170	                    const worldY = baseY + use.y;
171	                    const key = `${worldX}_${worldY}`;
172	
173	                    entities.push({
174	                        id: objId,
175	                        type: 'object',
176	                        name: objDef.name || `Object_${objId}`,
177	                        x: worldX,
178	                        y: worldY,
179	                        plane: use.plane,
180	                        rotation: use.rotation
181	                    });
182	
183	                    if (!collisionMatrix[key]) continue;
184	
185	                    const rotation = use.rotation;
186	                    const type = use.type;
187	
188	                    // Wall logic (Directional blocking)
189	                    if (type >= 0 && type <= 3) {
190	                        if (rotation === 0) collisionMatrix[key].edges.westBlocked = true;
191	                        if (rotation === 1) collisionMatrix[key].edges.northBlocked = true;
192	                        if (rotation === 2) collisionMatrix[key].edges.eastBlocked = true;
193	                        if (rotation === 3) collisionMatrix[key].edges.southBlocked = true;
194	                    }
195	                    // Solid object
196	                    else if (type === 10 && !objDef.probably_nocollision) {
197	                        collisionMatrix[key].walkable = false;
198	                    }
199	                }
200	            }
201	
202	            console.log(`[SovereignWorldLoader] Direct Materialization Complete for [${rx}, ${ry}]: ${entities.length} entities.`);
203	            return { regionId, entities, collisionMatrix };
204	        } catch (e) {
205	            console.error(`[SovereignWorldLoader] Direct Materialization Failed for [${rx}, ${ry}]:`, e);
206	            return null;
207	        }
208	    }
209	
210	    private async getObjectDef(id: number) {
211	        const data = await this.cacheSubstrate!.getFile(cacheMajors.objects, id);
212	        if (!data) return { name: `Object_${id}`, probably_nocollision: false };
213	        return parse.object.read(data, this.cacheSubstrate!);
214	    }
215	
216	    /**
217	     * Normalizes different JSON formats into a standard Sovereign structure.
218	     */
219	    private normalizeData(data: any): RegionTruth {
220	        const entities: SovereignEntity[] = [];
221	        const collisionMatrix: Record<string, CollisionTile> = {};
222	
223	        // Handle 'unified_extract' format (objects, tileFlags)
224	        if (data.objects) {
225	            data.objects.forEach((obj: any) => {
226	                entities.push({
227	                    id: obj.id,
228	                    type: 'object',
229	                    name: obj.name || `Object_${obj.id}`,
230	                    x: obj.worldX || obj.x,
231	                    y: obj.worldZ || obj.z,
232	                    plane: obj.plane,
233	                    rotation: obj.rotation,
234	                    wikiUrl: obj.wikiUrl
235	                });
236	            });
237	        }
238	
239	        // Handle 'world_extract' format (entities array)
240	        if (data.entities) {
241	            data.entities.forEach((ent: any) => {
242	                entities.push({
243	                    id: ent.id,
244	                    type: ent.type,
245	                    name: ent.name,
246	                    x: ent.x,
247	                    y: ent.y,
248	                    plane: ent.plane,
249	                    rotation: ent.rotation,
250	                    wikiUrl: ent.wikiUrl
251	                });
252	            });
253	        }
254	
255	        // Phase B3 collision_matrix (semantic edges + surface types)
256	        if (data.collision_matrix) {
257	            for (const [key, tile] of Object.entries(data.collision_matrix)) {
258	                const t = tile as any;
259	                collisionMatrix[key] = {
260	                    walkable: t.walkable ?? true,
261	                    surfaceType: t.surfaceType ?? 'terrain',
262	                    sourceFlags: t.sourceFlags ?? 0,
263	                    edges: {
264	                        northBlocked: t.edges?.northBlocked ?? false,
265	                        southBlocked: t.edges?.southBlocked ?? false,
266	                        eastBlocked: t.edges?.eastBlocked ?? false,
267	                        westBlocked: t.edges?.westBlocked ?? false,
268	                    }
269	                };
270	            }
271	        } else if (data.tileFlags) {
272	            // Legacy fallback: convert flat tileFlags to collision tiles
273	            this.buildMatrixFromFlags(data.tileFlags, collisionMatrix);
274	        }
275	
276	        return {
277	            regionId: data.regionId || (data.chunkX << 8 | data.chunkZ),
278	            entities,
279	            collisionMatrix
280	        };
281	    }
282	
283	    private buildMatrixFromFlags(flags: any[], out: Record<string, CollisionTile>) {
284	        if (!flags) return;
285	        flags.forEach(f => {
286	            const key = `${f.x}_${f.z}`;
287	            out[key] = {
288	                walkable: f.collision === 0,
289	                surfaceType: 'terrain',
290	                sourceFlags: f.collision || 0,
291	                edges: {}
292	            };
293	        });
294	    }
295	}
